def check_n(n, max_K=10):
    c = []
    for K in range(1, max_K + 1):
        # c_1(K) = (K+1)! * (1 - sum_{j=2}^K j^{n-1}/j!)
        # To keep it as integers, c_1(K) = (K+1)! - sum_{j=2}^K (K+1)!/j! * j^{n-1}
        val = 1
        # This is (K+1)!
        import math
        val = math.factorial(K+1)
        sum_val = 0
        for j in range(2, K + 1):
            sum_val += (math.factorial(K+1) // math.factorial(j)) * (j**(n-1))
        c_K = val - sum_val
        c.append(c_K)

    # Check consistency: c_K \equiv c_{K-1} \pmod{K!}
    # c is 0-indexed, so c[K-1] is c_1(K)
    # We need c[K-1] \equiv c[K-2] \pmod{K!} for K=2, 3, ...
    # Wait, the index is a bit confusing.
    # c[0] is c_1(1)
    # c[1] is c_1(2)
    # c[2] is c_1(3)
    # ...
    # c[K-1] is c_1(K)
    # We need c_1(K) \equiv c_1(K-1) \pmod{K!}
    # So c[K-1] \equiv c[K-2] \pmod{K!}
    for K in range(2, max_K + 1):
        if c[K-1] % math.factorial(K) != c[K-2] % math.factorial(K):
            return False, c
    return True, c

for n in range(1, 11):
    res, data = check_n(n)
    print(f"n={n}: {res}, data={data}")

