def check_n(n, max_k=10):
    S = [0] * (max_k + 1)
    # S_k = k S_{k-1} + k^{n-1}
    # We need S_k \equiv S_{k-1} \pmod{(k-1)!}
    # which is k S_{k-1} + k^{n-1} \equiv S_{k-1} \pmod{(k-1)!}
    # (k-1) S_{k-1} + k^{n-1} \equiv 0 \pmod{(k-1)!}

    # Let's just compute S_k modulo something to avoid overflow
    # But we need to check modulo (k-1)!. So we need to handle large numbers.

    # Use arbitrary precision integers (Python does this automatically)
    S[0] = 0
    for k in range(1, max_k + 1):
        S[k] = k * S[k-1] + k**(n-1)

    for k in range(2, max_k + 1):
        mod = math.factorial(k-1)
        if (k-1) * S[k-1] + k**(n-1) % mod != 0:
            return False
    return True

for n in range(1, 20):
    if check_n(n):
        print(f"n={n} is a solution")
